1	import { describe, test, expect } from 'vitest';
2	import { Button } from './zimmButton.css';
3	
4	/**
5	 * index.test.tsx renders through the real ChakraProvider/theme (not mocked), so the base
6	 * (non-media-query) recipe values ARE exercised there. But JSDOM does not evaluate real
7	 * @media breakpoints, so a rendered-component test can't verify what changes — or doesn't —
8	 * inside a size's @media block. These assertions read the plain recipe object directly.
9	 */
10	describe('ZimmButton recipe — social size padding regression guard', () => {
11	  test('px is 32px (action-padding-h-lg) at the base/mobile level, not the 20px md-tier token', () => {
12	    // Corrected 2026-09: this previously read var(--zimm-size-action-padding-h-md) (20px),
13	    // matching a comment that wrongly claimed Figma had padding step down on mobile — live
14	    // Figma inspection confirmed padding is 32px at every breakpoint.
15	    // Button.sizes is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts
16	    // always passes a sizes object — guaranteed non-null at runtime.
17	    const social = Button.sizes!.social as Record<string, unknown>;
18	    expect(social.px).toBe('var(--zimm-size-action-padding-h-lg)');
