1	import React, { forwardRef, useEffect, useImperativeHandle, useRef } from 'react';
2	import { chakra, useBreakpointValue, useStyleConfig } from '@chakra-ui/react';
3	import { ZimmDropdown, getDropdownOptionId } from 'app/components/ui-kits/atoms/zimmDropdown';
4	import { ZimmDropdownItem } from 'app/components/ui-kits/atoms/zimmDropdownItem';
5	import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
6	import { useZimmSizeSelector, deriveSizeStatus } from 'app/hooks/useZimmSizeSelector';
7	import { useIntl } from 'react-intl';
8	
9	type SizeValue = {
10	  value: string;
11	  name: string;
12	  orderable: boolean;
13	};
14	
15	type ZimmSizeSelectorProps = {
16	  variationAttribute: {
17	    id: string;
18	    name: string;
19	    values: ReadonlyArray<SizeValue>;
20	  };
21	  selectedValue: string | null;
22	  onSelectionChange: (value: string) => void;
23	  showError?: boolean;
24	  /** Overrides the default "Size required" error string when provided. */
25	  errorMessage?: string;
26	  /**
27	   * `product.inventory.backorderable` — a product-level flag. Turns unorderable sizes into
28	   * "notify me" rows rather than "out of stock" ones.
29	   */
30	  isBackorderable?: boolean;
31	  /**
32	   * Trigger label when nothing is selected. Forward-compatible with the future Unavailable /
33	   * Coming Soon states, which pass their own copy.
34	   */
35	  placeholder?: string;
36	  onFindYourSizeClick?: () => void;
37	  /** Opens the Size Guide drawer. Wired to the "Size Guide" link beside the size selector. */
38	  onSizeGuideClick?: () => void;
39	  onNotifyMeClick?: (value: string) => void;
40	};
41	
42	/** Imperative handle exposed via `ref` for programmatic focus (A4). */
43	export type ZimmSizeSelectorHandle = {
44	  /** Moves focus to the dropdown trigger button. No-op for one-size products (no trigger rendered). */
45	  focusTrigger: () => void;
46	};
47	
48	/**
49	 * Molecule — flush underline-style size selector for the PDP (SFCC-92).
50	 *
51	 * Composes ZimmDropdown (trigger + panel + keyboard nav) with ZimmDropdownItem rows, and
52	 * renders a plain "One size" label instead when the product has a single variation value.
53	 *
54	 * Every size is selectable regardless of stock (Option A, confirmed over PRD-014) — the
55	 * parent is expected to set Add to Bag's `ariaDisabled` from the selected size's status.
56	 */
57	export const ZimmSizeSelector = forwardRef<ZimmSizeSelectorHandle, ZimmSizeSelectorProps>(
58	  (
59	    {
60	      variationAttribute,
61	      selectedValue,
62	      onSelectionChange,
63	      showError = false,
64	      errorMessage: errorMessageProp,
65	      isBackorderable = false,
66	      placeholder,
67	      onFindYourSizeClick,
68	      onSizeGuideClick,
69	      onNotifyMeClick,
70	    },
71	    ref,
72	  ) => {
73	    const { id, values } = variationAttribute;
74	
75	    const triggerButtonRef = useRef<HTMLButtonElement | null>(null);
76	
77	    useImperativeHandle(ref, () => ({
78	      focusTrigger: () => triggerButtonRef.current?.focus(),
79	    }));
80	
81	    // Both fetched unconditionally per React rules of hooks (early return is below).
82	    const intl = useIntl();
83	    const oneSizeStyles = useStyleConfig('ZimmSizeSelector');
84	    const resolvedPlaceholder =
85	      placeholder ?? intl.formatMessage({ defaultMessage: 'Size', id: 'zimm_size_selector.placeholder' });
86	
87	    const hookItems = values.map((v) => ({ value: v.value, orderable: v.orderable }));
88	    const { hasError, select, setError, clearError } = useZimmSizeSelector(hookItems);
89	
90	    // Sync showError prop into hook state.
91	    useEffect(() => {
92	      if (showError) {
93	        setError();
94	      } else {
95	        clearError();
96	      }
97	    }, [showError, setError, clearError]);
98	
99	    // Option B (confirmed): a one-size product is simply a variation attribute with a single
100	    // value — SFCC exposes no explicit isOneSize flag.
101	    const isOneSize = values.length === 1;
102	    const singleValue = values[0]?.value;
103	
104	    // AC 11 — the lone size counts as selected with no interaction, so Add to Bag is live on
105	    // load. Guarded on selectedValue so a controlled parent re-render can't loop.
106	    useEffect(() => {
107	      if (isOneSize && singleValue && selectedValue !== singleValue) {
108	        onSelectionChange(singleValue);
109	      }
110	    }, [isOneSize, singleValue, selectedValue, onSelectionChange]);
111	
112	    // sizeGuideLink and growUnderline are mutually exclusive — growUnderline swaps the inner
113	    // span's border for a ::after that only scales up on :hover, which mobile never fires.
114	    const isMobile = useBreakpointValue({ base: true, sm: false }, { fallback: 'sm' });
115	
116	    const selectedItem = values.find((v) => v.value === selectedValue);
117	    const triggerLabel = selectedItem?.name;
118	
119	    // The single shared activation path for a size row — passed to ZimmDropdown as
120	    // `onItemSelect` (the parent panel's own Enter/Space keyboard handling calls this directly,
121	    // bypassing each item's own onClick prop entirely) AND wrapped inside each ZimmDropdownItem's
122	    // `onClick` (mouse/pointer activation). Deriving notify-me here, rather than inside
123	    // ZimmDropdownItem, keeps both input modalities behind one function instead of two
124	    // independently-maintained call paths that could silently drift apart.
125	    const handleItemSelect = (index: number) => {
126	      const item = values[index];
127	      if (!item) return;
128	      // No orderable check: out-of-stock and notify-me rows are selectable under Option A.
129	      select(item.value);
130	      onSelectionChange(item.value);
131	      if (deriveSizeStatus(item, isBackorderable) === 'notify-me') {
132	        onNotifyMeClick?.(item.value);
133	      }
134	    };
135	
136	    if (isOneSize) {
137	      return (
138	        // Matches the standard trigger's geometry minus the bottom border and chevron.
139	        // role="status" announces the label on mount, since the size is already selected (A8).
140	        <chakra.p role="status" __css={oneSizeStyles}>
141	          {intl.formatMessage({ defaultMessage: 'One size', id: 'zimm_size_selector.one_size' })}
142	        </chakra.p>
143	      );
144	    }
145	
146	    // ZimmDropdown's triggerRowRight places "Find your size" beside the trigger in the same
147	    // row. The panel renders as a sibling below the full row (Figma node 6967:13860).
148	    // The footer row (Figma node 6967:13886) sits inside the panel after the listbox items.
149	    return (
150	      <ZimmDropdown
151	        id={`zimm-size-selector-${id}`}
152	        triggerCallbackRef={(el) => {
153	          triggerButtonRef.current = el;
154	        }}
155	        label={resolvedPlaceholder}
156	        value={triggerLabel}
157	        hasError={hasError}
158	        errorMessage={
159	          errorMessageProp ??
160	          intl.formatMessage({
161	            defaultMessage: 'Size required',
162	            id: 'zimm_size_selector.error.size_required',
163	          })
164	        }
165	        itemCount={values.length}
166	        onItemSelect={handleItemSelect}
167	        triggerRowRight={
168	          <ZimmNavItem
169	            label={intl.formatMessage({ defaultMessage: 'Find your size', id: 'zimm_size_selector.find_your_size' })}
170	            variant={isMobile ? 'sizeGuideLink' : 'sizeGuide'}
171	            growUnderline={!isMobile}
172	            onClick={onFindYourSizeClick}
173	            sx={{ flexShrink: 0, whiteSpace: 'nowrap' }}
174	          />
175	        }
176	        renderItems={({ focusedIndex, triggerId, panelId, close }) => (
177	          <>
178	            <chakra.ul role="listbox" aria-labelledby={triggerId} padding={0} margin={0}>
179	              {values.map((item, index) => (
180	                <ZimmDropdownItem
181	                  key={item.value}
182	                  id={getDropdownOptionId(panelId, index)}
183	                  zimmSize={item.name}
184	                  status={deriveSizeStatus(item, isBackorderable)}
185	                  isSelected={item.value === selectedValue}
186	                  isFocused={focusedIndex === index}
187	                  onClick={() => {
188	                    handleItemSelect(index);
